def transform(grid):
    # A single zero divider separates two color fields. Fill an output with
    # their shared color, using the size of either field.
    h, w = len(grid), len(grid[0])
    if all(row[w//2] == 0 for row in grid):
        left = {v for row in grid for v in row[:w//2] if v}
        right = {v for row in grid for v in row[w//2+1:] if v}
        c = next(iter(left & right))
        return [[c] * (w//2) for _ in range(h)]
    # horizontal divider
    d = next(r for r,row in enumerate(grid) if all(v == row[0] for v in row) and len(set(row)) == 1)
    top = {v for row in grid[:d] for v in row if v}
    bottom = {v for row in grid[d+1:] for v in row if v}
    c = next(iter(top & bottom))
    n = len(grid[0])
    return [[c]*n for _ in range(n)]
PY

